#pragma comment(lib, "bcrypt.lib")
#pragma comment(lib, "psapi.lib")
using Query = void *(__cdecl *)(uint32_t);
constexpr uint32_t kGetArchInfo = 0xd8265d24;
static std::wstring ModulePath(HMODULE module) { std::vector<wchar_t> b(512); for(;;){DWORD n=GetModuleFileNameW(module,b.data(),static_cast<DWORD>(b.size()));if(!n)return{};if(n<b.size()-1)return std::wstring(b.data(),n);b.resize(b.size()*2);} }
static bool HashFile(const std::wstring& path,std::string& out){std::ifstream f(path,std::ios::binary);if(!f)return false;BCRYPT_ALG_HANDLE a{};BCRYPT_HASH_HANDLE h{};DWORD cb=0,obj=0;if(BCryptOpenAlgorithmProvider(&a,BCRYPT_SHA256_ALGORITHM,nullptr,0)<0)return false;bool ok=BCryptGetProperty(a,BCRYPT_OBJECT_LENGTH,reinterpret_cast<PUCHAR>(&obj),sizeof(obj),&cb,0)>=0;std::vector<uint8_t> ob(obj),d(32);ok=ok&&BCryptCreateHash(a,&h,ob.data(),obj,nullptr,0,0)>=0;std::vector<char>b(1<<16);while(ok&&f){f.read(b.data(),b.size());auto n=f.gcount();if(n)ok=BCryptHashData(h,reinterpret_cast<PUCHAR>(b.data()),static_cast<ULONG>(n),0)>=0;}ok=ok&&BCryptFinishHash(h,d.data(),static_cast<ULONG>(d.size()),0)>=0;if(h)BCryptDestroyHash(h);BCryptCloseAlgorithmProvider(a,0);if(!ok)return false;char text[65]{};for(size_t i=0;i<d.size();++i)sprintf_s(text+i*2,3,"%02X",d[i]);out=text;return true;}
static bool Readable(DWORD p){return (p&(PAGE_READONLY|PAGE_READWRITE|PAGE_WRITECOPY|PAGE_EXECUTE_READ|PAGE_EXECUTE_READWRITE|PAGE_EXECUTE_WRITECOPY))!=0;}
static void PrintVq(const char*prefix,const MEMORY_BASIC_INFORMATION&m){printf("%sBASE=%p\n%sALLOCATION_BASE=%p\n%sALLOCATION_PROTECT=0x%lX\n%sREGION_SIZE=%zu\n%sSTATE=0x%lX\n%sPROTECT=0x%lX\n%sTYPE=0x%lX\n",prefix,m.BaseAddress,prefix,m.AllocationBase,prefix,m.AllocationProtect,prefix,m.RegionSize,prefix,m.State,prefix,m.Protect,prefix,m.Type);}
static void PrintFile(const char*prefix,const std::wstring&path){WIN32_FILE_ATTRIBUTE_DATA a{};LARGE_INTEGER s{};if(GetFileAttributesExW(path.c_str(),GetFileExInfoStandard,&a)){s.HighPart=a.nFileSizeHigh;s.LowPart=a.nFileSizeLow;}std::string hash;HashFile(path,hash);printf("%sPATH=%ls\n%sSIZE=%lld\n%sSHA256=%s\n",prefix,path.c_str(),prefix,s.QuadPart,prefix,hash.c_str());}
int main(){wchar_t sd[MAX_PATH]{};if(!GetSystemDirectoryW(sd,MAX_PATH))return 2;std::wstring system_path=std::wstring(sd)+L"\\nvapi64.dll";PrintFile("NVAPI_",system_path);HMODULE nvapi=LoadLibraryExW(L"nvapi64.dll",nullptr,LOAD_LIBRARY_SEARCH_SYSTEM32);if(!nvapi){printf("LOAD_FAILED=true\n");return 2;}auto nvapi_path=ModulePath(nvapi);MODULEINFO nmi{};GetModuleInformation(GetCurrentProcess(),nvapi,&nmi,sizeof(nmi));auto base=reinterpret_cast<uint8_t*>(nmi.lpBaseOfDll);auto size=nmi.SizeOfImage;printf("NVAPI_MAPPED_PATH=%ls\nNVAPI_BASE=%p\nNVAPI_SIZE_OF_IMAGE=0x%lX\n",nvapi_path.c_str(),base,size);auto q=reinterpret_cast<Query>(GetProcAddress(nvapi,"nvapi_QueryInterface"));if(!q){FreeLibrary(nvapi);return 2;}void*raw=q(kGetArchInfo);printf("QUERY_ID=0x%08X\nQUERY_TARGET=%p\nQUERY_TARGET_DELTA=0x%llX\n",kGetArchInfo,raw,raw?static_cast<unsigned long long>(reinterpret_cast<uint8_t*>(raw)-base):0ull);if(!raw){FreeLibrary(nvapi);return 2;}MEMORY_BASIC_INFORMATION tm{};if(VirtualQuery(raw,&tm,sizeof(tm))!=sizeof(tm)){printf("TARGET_CLASS=INVALID_OR_UNREADABLE\n");FreeLibrary(nvapi);return 2;}PrintVq("TARGET_VQ_",tm);const bool committed=tm.State==MEM_COMMIT&&Readable(tm.Protect);HMODULE owner=nullptr;const bool owner_found=GetModuleHandleExW(GET_MODULE_HANDLE_EX_FLAG_FROM_ADDRESS|GET_MODULE_HANDLE_EX_FLAG_UNCHANGED_REFCOUNT,reinterpret_cast<LPCWSTR>(raw),&owner)!=FALSE;printf("OWNER_MODULE_FOUND=%s\n",owner_found?"true":"false");MODULEINFO omi{};std::wstring owner_path;if(owner_found){GetModuleInformation(GetCurrentProcess(),owner,&omi,sizeof(omi));owner_path=ModulePath(owner);printf("OWNER_PATH=%ls\nOWNER_BASE=%p\nOWNER_SIZE_OF_IMAGE=0x%lX\n",owner_path.c_str(),omi.lpBaseOfDll,omi.SizeOfImage);}const auto nv_begin=reinterpret_cast<uintptr_t>(base),nv_end=nv_begin+size;const auto target=reinterpret_cast<uintptr_t>(raw);const bool in_nv=target>=nv_begin&&target<nv_end;const bool in_owner=owner_found&&target>=reinterpret_cast<uintptr_t>(omi.lpBaseOfDll)&&target<reinterpret_cast<uintptr_t>(omi.lpBaseOfDll)+omi.SizeOfImage;printf("TARGET_IN_NVAPI=%s\nTARGET_IN_OWNER=%s\n",in_nv?"true":"false",in_owner?"true":"false");if(!committed){printf("TARGET_CLASS=INVALID_OR_UNREADABLE\n");FreeLibrary(nvapi);return 2;}const size_t max_window=48;const auto region_end=reinterpret_cast<uintptr_t>(tm.BaseAddress)+tm.RegionSize;const size_t count=region_end>target?((region_end-target)<max_window?(region_end-target):max_window):0;if(count==0){printf("TARGET_CLASS=INVALID_OR_UNREADABLE\n");FreeLibrary(nvapi);return 2;}std::vector<uint8_t> bytes(count);memcpy(bytes.data(),raw,count);printf("PROLOGUE_BYTES=");for(auto b:bytes)printf("%02X",b);putchar('\n');if(in_nv)printf("TARGET_CLASS=DIRECT_NVAPI_IMAGE\n");else if(owner_found&&tm.Type==MEM_IMAGE)printf("TARGET_CLASS=OTHER_IMAGE_MODULE\n");else if(tm.Type==MEM_PRIVATE)printf("TARGET_CLASS=PRIVATE_DISPATCH_THUNK\n");else if(tm.Type==MEM_MAPPED)printf("TARGET_CLASS=MAPPED_NON_IMAGE\n");else printf("TARGET_CLASS=INVALID_OR_UNREADABLE\n");FreeLibrary(nvapi);return 0;}
